package net.battlespades.bot;

import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.world.MutableWorld;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotVectors.*;

/** Owner-thread local collision steering; never advances a route or moves a body. */
public final class BotLiveSteering {
    public interface World {long topology();boolean solid(int x,int y,int z);boolean water(int x,int y);boolean clip(double x,double y,double z);}
    public record Body(int id,int generation,Vector position,Vector velocity,boolean grounded,boolean wade,boolean crouch,int jetpack){}
    /** Shared across all motors for one fixed step; compatible cached probes may defer after the first refresh. */
    public static final class Budget {private final Thread owner=Thread.currentThread();private int probes;public void reset(){owned();probes=0;}public int probes(){owned();return probes;}private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Steering budget outside owner");}}
    private final Thread owner=Thread.currentThread();private final World world;private final Budget budget;
    private List<Object> waypointKey,cacheKey;private boolean waypointResult;private Vector cachedPosition,cachedDirection=ZERO;private double cacheUntil;
    public BotLiveSteering(World world,Budget budget){this.world=Objects.requireNonNull(world);this.budget=Objects.requireNonNull(budget);}
    public static World world(MutableWorld terrain){return new World(){public long topology(){return terrain.topologyVersion();}public boolean solid(int x,int y,int z){return terrain.solid(x,y,z);}public boolean water(int x,int y){return terrain.surfaceZ(x,y)>=239;}public boolean clip(double x,double y,double z){if(x<0||x>=512||y<0||y>=512)return true;if(z<0)return false;int cell=(int)Math.floor(z);if(cell==239)cell--;else if(cell>=240)return true;return terrain.solid((int)Math.floor(x),(int)Math.floor(y),cell);}};}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Live steering outside owner");budget.owned();}
    public void clear(){owned();waypointKey=cacheKey=null;cachedPosition=null;cachedDirection=ZERO;cacheUntil=0;}
    public static boolean travelTarget(Intent i){return i.movement().travelSource()!=null&&i.movement().travelWaypoint()!=null&&Set.of(Affordance.WALK,Affordance.CROUCH,Affordance.DROP,Affordance.JUMP).contains(i.movement().affordance())&&i.action().kind()==ActionKind.NONE&&(i.look()==null||!i.look().visible());}
    public static String travelPurpose(Intent i){var m=i.movement();return m.gazeWaypoint()!=null?"travel":m.travelSource()!=null&&m.travelWaypoint()!=null&&distance(m.travelSource(),m.travelWaypoint())<=2.25?"traverse":"travel";}
    public static Vector travelDirection(Body b,Intent i){var m=i.movement();var requested=m.direction();if(!travelTarget(i))return requested;double strength=Math.hypot(requested.x(),requested.y());if(strength<=1e-6)return requested;var source=m.travelSource();var target=m.travelWaypoint();double ix=target.x()-source.x(),iy=target.y()-source.y(),length=Math.hypot(ix,iy);if(length<=1e-6)return requested;double dx=target.x()-b.position().x(),dy=target.y()-b.position().y(),remaining=Math.hypot(dx,dy),along=(dx*ix+dy*iy)/length,across=Math.abs(dx*iy-dy*ix)/length;boolean height=b.position().z()<=target.z()+1;if(height&&(remaining<=.35||along<=0&&across<=.55)||remaining<=1e-6)return ZERO;double cosine=(ix*requested.x()+iy*requested.y())/(length*strength),sine=(ix*requested.y()-iy*requested.x())/(length*strength);return new Vector((dx*cosine-dy*sine)/remaining*strength,(dx*sine+dy*cosine)/remaining*strength,requested.z());}
    public Vector direction(Body b,Vector requested,Affordance affordance,int drop,double now){
        owned();boolean ordinary=ordinary(affordance),water=b.wade()&&(affordance==Affordance.SWIM||affordance==Affordance.JUMP);var key=List.<Object>of(rounded(requested.x()*100),rounded(requested.y()*100),rounded(requested.z()*100),affordance,world.topology(),b.wade(),drop);double travel=cachedPosition==null?Double.POSITIVE_INFINITY:distance(cachedPosition,b.position());if(ordinary&&key.equals(cacheKey)&&cachedPosition!=null&&(now<cacheUntil&&travel<=1.25||travel<=1.75&&budget.probes>=1))return cachedDirection;budget.probes++;
        Vector result=ZERO;if(live(b,requested,affordance,drop))result=requested;else if(ordinary||water){double length=Math.hypot(requested.x(),requested.y());if(length>1e-6){double dx=requested.x()/length,dy=requested.y()/length;
            if(ordinary){double cx=Math.abs(dx)>=Math.abs(dy)?Math.copySign(.65,dx):Math.floor(b.position().x())+.5-b.position().x(),cy=Math.abs(dx)>=Math.abs(dy)?Math.floor(b.position().y())+.5-b.position().y():Math.copySign(.65,dy),cl=Math.hypot(cx,cy);var centered=new Vector(cx/cl*length,cy/cl*length,requested.z());double across=Math.abs(dx)>=Math.abs(dy)?b.position().y():b.position().x(),beside=Math.abs(dx)>=Math.abs(dy)?dy:dx;if(Math.floor(across+beside*.65)==Math.floor(across)&&distance(centered,requested)>1e-6&&live(b,centered,affordance,drop))result=centered;
                var x=new Vector(Math.copySign(length,dx),0,requested.z());var y=new Vector(0,Math.copySign(length,dy),requested.z());for(var candidate:Math.abs(dy)>Math.abs(dx)?List.of(y,x):List.of(x,y)){if(!result.equals(ZERO))break;if(distance(candidate,requested)<=1e-6||candidate.x()*dx+candidate.y()*dy<=1e-6)continue;if(live(b,candidate,affordance,drop)){result=candidate;break;}}}
            double preferred=((b.id()+b.generation())&1)!=0?-1:1;for(int magnitude:water?new int[]{20,40,60,80}:new int[]{20,40,60}){if(!result.equals(ZERO))break;for(double sign:new double[]{preferred,-preferred}){double angle=Math.toRadians(magnitude)*sign,cos=Math.cos(angle),sin=Math.sin(angle);var candidate=new Vector((dx*cos-dy*sin)*length,(dx*sin+dy*cos)*length,requested.z());if(live(b,candidate,affordance,drop)){result=candidate;break;}}}
        }}if(ordinary){cacheKey=key;cachedDirection=result;cachedPosition=b.position();cacheUntil=now+.05;}return result;
    }
    private static boolean ordinary(Affordance a){return a==Affordance.WALK||a==Affordance.CROUCH;}
    private static long rounded(double v){return (long)Math.rint(v);}
    public boolean live(Body b,Vector requested,Affordance affordance,int drop){
        owned();double length=Math.hypot(requested.x(),requested.y());if(length<=1e-6)return true;double dx=requested.x()/length,dy=requested.y()/length,speed=Math.hypot(b.velocity().x(),b.velocity().y()),reach=ordinary(affordance)&&!b.wade()?Math.min(5,.65+speed*10):.65;int walkDrop=ordinary(affordance)?drop:1;var key=List.<Object>of(rounded(b.position().x()*8),rounded(b.position().y()*8),rounded(b.position().z()*8),rounded(dx*100),rounded(dy*100),world.topology(),b.wade(),b.grounded(),rounded(reach*100),affordance,walkDrop);if(key.equals(waypointKey))return waypointResult;var immediate=probes(b,dx,dy,Math.min(.65,reach));boolean result=surfaces(b,immediate,affordance,walkDrop);
        if(!result&&ordinary(affordance)&&speed<.1&&b.grounded()&&surface(b,immediate.getFirst().x(),immediate.getFirst().y(),affordance,1)&&!surface(b,b.position().x(),b.position().y(),affordance,1))result=clear(b,immediate.subList(1,3));
        if(result&&ordinary(affordance)&&!b.wade())result=!lowRoof(b,immediate.getFirst().x(),immediate.getFirst().y());if(result&&ordinary(affordance)&&!b.wade()&&reach>.65)for(int index=2;index<=(int)Math.ceil(reach/.5);index++){for(var p:probes(b,dx,dy,Math.min(reach,index*.5)))if(world.water((int)Math.floor(p.x()),(int)Math.floor(p.y()))){result=false;break;}if(!result)break;}
        if(!result&&(affordance==Affordance.DROP||walkDrop>1))result=surface(b,immediate.getFirst().x(),immediate.getFirst().y(),affordance,walkDrop)&&clear(b,immediate.subList(1,3));if(!result&&affordance==Affordance.JUMP&&clear(b,immediate))result=surfaces(b,probes(b,dx,dy,2.05),affordance,1);waypointKey=key;waypointResult=result;return result;
    }
    private static List<Vector> probes(Body b,double dx,double dy,double distance){double x=b.position().x()+dx*distance,y=b.position().y()+dy*distance,sx=-dy*.45,sy=dx*.45;return List.of(new Vector(x,y,0),new Vector(x+sx,y+sy,0),new Vector(x-sx,y-sy,0));}
    private boolean surfaces(Body b,List<Vector> points,Affordance a,int drop){for(var p:points)if(!surface(b,p.x(),p.y(),a,drop))return false;return true;}
    private boolean clear(Body b,List<Vector> points){for(var p:points)if(world.clip(p.x(),p.y(),b.position().z())||world.clip(p.x(),p.y(),b.position().z()+1))return false;return true;}
    public boolean lowRoof(Body b,double x,double y){owned();if(!b.grounded()||b.crouch())return false;int feet=(int)Math.rint(b.position().z()+2.25)-1;boolean step=false,roof=false;var columns=new HashSet<List<Integer>>();for(double dx:new double[]{-.449999988079071,.449999988079071})for(double dy:new double[]{-.449999988079071,.449999988079071})columns.add(List.of((int)(float)(x+dx),(int)(float)(y+dy)));for(var c:columns){if(world.solid(c.get(0),c.get(1),feet-1)||world.solid(c.get(0),c.get(1),feet-2))continue;step|=world.solid(c.get(0),c.get(1),feet);roof|=world.solid(c.get(0),c.get(1),feet-3);}return step&&roof;}
    public boolean surface(Body b,double x,double y,Affordance a,int drop){
        owned();int cx=(int)Math.floor(x),cy=(int)Math.floor(y);boolean water=world.water(cx,cy);double z=b.position().z();if(a==Affordance.JETPACK)return b.jetpack()>=66&&b.jetpack()<=69&&!b.wade()&&z<237&&!world.clip(x,y,z-1)&&!world.clip(x,y,z)&&!world.clip(x,y,z+1);
        if((b.wade()||a==Affordance.SWIM)&&(water||z>=235.75)){if(!world.clip(x,y,238)&&!world.clip(x,y,237))return true;if(a!=Affordance.JUMP)return false;}if(a!=Affordance.JUMP&&(world.clip(x,y,z)||world.clip(x,y,z+1)))return false;if(!b.wade()&&water&&a!=Affordance.SWIM)return false;int support=(int)Math.rint(z+2.25),climb=a==Affordance.JUMP?2:a==Affordance.JETPACK?8:1,fall=a==Affordance.JUMP?3:a==Affordance.DROP?4:a==Affordance.JETPACK?8:drop;for(int h=Math.max(2,support-climb);h<Math.min(240,support+fall+1);h++)if(world.solid(cx,cy,h)&&!world.solid(cx,cy,h-1)&&!world.solid(cx,cy,h-2))return true;return false;
    }
}
